<script setup lang="ts">import {books} from '~/data/content';const {library,toggleBook}=useProgress()</script><template><main class="shell py-10"><h1 class="heading">📚 Իմ գրադարանը</h1><p class="muted mb-6">Պահպանիր սիրելի գրքերը։ Ամբողջական տեքստերը կավելացվեն միայն օգտագործման իրավունքը ստուգելուց հետո։</p><div class="grid md:grid-cols-3 gap-4"><div v-for="b in books" :key="b.id" class="panel p-6"><div class="text-5xl gold mb-5">▤</div><h2 class="text-xl font-bold">{{b.title}}</h2><p class="muted mt-2">{{b.author}}</p><button @click="toggleBook(b.id)" class="btn-secondary mt-6">{{library.includes(b.id)?'✓ Իմ գրադարանում է':'+ Ավելացնել գրադարան'}}</button></div></div></main></template>